<?php
session_start();
require '../../config/db.php';
if (!isset($_SESSION['admin_id'])) { header('Location: ../../auth/login-admin.php'); exit; }
function h($v){return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');}
$admin_id=(int)$_SESSION['admin_id'];
$cliente_id=isset($_GET['cliente_id'])?(int)$_GET['cliente_id']:0;
$stmt=$pdo->prepare('SELECT id,nome,email,telefone,logo FROM clientes WHERE id=?');$stmt->execute([$cliente_id]);$cliente=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$cliente){header('Location: mensagens.php');exit;}
$stmt=$pdo->prepare("SELECT m.* FROM mensagens m WHERE (m.remetente_id=? AND m.destinatario_id=?) OR (m.remetente_id=? AND m.destinatario_id=?) ORDER BY m.data ASC, m.id ASC");
$stmt->execute([$admin_id,$cliente_id,$cliente_id,$admin_id]);$mensagens=$stmt->fetchAll(PDO::FETCH_ASSOC);
$pdo->prepare('UPDATE mensagens SET lida=1 WHERE destinatario_id=? AND remetente_id=?')->execute([$admin_id,$cliente_id]);
$lastId=0; foreach($mensagens as $m){$lastId=max($lastId,(int)$m['id']);}
$stmt=$pdo->prepare('SELECT status, protocolo, titulo, descricao, data FROM solicitacoes WHERE cliente_id=? ORDER BY data DESC LIMIT 1');$stmt->execute([$cliente_id]);$ultima=$stmt->fetch(PDO::FETCH_ASSOC);
$logo=!empty($cliente['logo'])?'../../uploads/clientes/logos/'.basename($cliente['logo']):'';
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Live Chat Técnico - <?=h($cliente['nome'])?></title><link rel="stylesheet" href="../../assets/css/helpdesk-pro.css"></head><body><div class="hd-page"><header class="hd-topbar"><div class="hd-container hd-topbar-inner"><div class="hd-brand"><div class="hd-client-logo-box"><?php if($logo):?><img src="<?=h($logo)?>" alt="Logo"><?php else:?>👤<?php endif;?></div><div><h1>Live Chat Técnico</h1><p>Conversa com <?=h($cliente['nome'])?> — atendimento com alerta em tempo quase real.</p></div></div><div class="hd-user"><a class="hd-chip" href="dashboard.php">Dashboard</a><a class="hd-chip" href="mensagens.php">Mensagens <b data-chat-badge></b></a><a class="hd-chip" href="financeiro.php?cliente_id=<?=$cliente_id?>">Financeiro</a><a class="hd-chip" href="../../auth/logout.php">Sair</a></div></div></header><main class="hd-main"><div class="hd-container"><div class="hd-grid"><section class="hd-card hd-live-chat-card"><div class="hd-live-chat-head"><div><h2>💬 <?=h($cliente['nome'])?></h2><p><?=h($cliente['email']??'')?> <?=!empty($cliente['telefone'])?' • '.h($cliente['telefone']):''?></p></div><span class="hd-live-status" id="hdLiveChatStatus">Online</span></div><div class="hd-live-chat-history" id="hdLiveChatHistory" data-last-id="<?=$lastId?>"><?php if(!$mensagens):?><div class="hd-empty hd-chat-empty">💬<strong>Nenhuma mensagem ainda</strong>Inicie a conversa com o cliente.</div><?php endif;?><?php foreach($mensagens as $m): $mine=(int)$m['remetente_id']===$admin_id; ?><div class="hd-chat-row <?=$mine?'mine':'other'?>" data-msg-id="<?=(int)$m['id']?>"><div class="hd-chat-bubble"><div class="hd-chat-meta"><?=$mine?'Você':'Cliente'?> • <?=date('d/m/Y H:i',strtotime($m['data']))?></div><div class="hd-chat-text"><?=nl2br(h($m['mensagem']))?></div></div></div><?php endforeach;?></div><form class="hd-live-chat-form" id="hdLiveChatForm"><textarea id="hdLiveChatInput" name="mensagem" placeholder="Digite sua resposta... Enter envia, Shift+Enter quebra linha." maxlength="2000" required></textarea><button class="hd-btn hd-btn-primary" type="submit">📤 Enviar</button></form></section><aside class="hd-sidebar"><section class="hd-card hd-card-pad"><div class="hd-section-head"><h3>Resumo do cliente</h3></div><div class="hd-sidebar-list"><div class="hd-mini"><strong><?=h($cliente['nome'])?></strong><p><?=h($cliente['email']??'')?></p></div><?php if($ultima):?><div class="hd-mini"><strong>Último chamado</strong><p><?=h($ultima['protocolo']?:($ultima['titulo']?:mb_substr($ultima['descricao'],0,80)))?></p><small class="hd-ticket-meta"><?=h(ucfirst($ultima['status']))?> • <?=date('d/m/Y',strtotime($ultima['data']))?></small></div><?php endif;?><a class="hd-btn hd-btn-outline" href="solicitacoes.php?id=<?=$cliente_id?>">📋 Chamados do cliente</a><a class="hd-btn hd-btn-outline" href="financeiro.php?cliente_id=<?=$cliente_id?>">💰 Financeiro do cliente</a><a class="hd-btn hd-btn-light" href="mailto:<?=h($cliente['email']??'')?>">📧 Email</a></div></section></aside></div></div></main></div><script>window.HD_CHAT_CONFIG={endpointBase:'../../controllers/',chatUrl:'mensagens.php',clienteId:<?=$cliente_id?>,chatInterval:4000,alertInterval:6000};</script><script src="../../assets/js/helpdesk-live-chat.js"></script><script src="../../assets/js/live-chat-alerts.js"></script><script src="../../assets/js/helpdesk-pro.js"></script></body></html>
